//! Advanced SIMD (NEON) tests.
//!
//! The cases live in `neon_vectors.rs`, generated by
//! `scripts/gen-neon-vectors.py`: encodings from clang and llvm-objdump,
//! expected registers, FPSR.QC and memory from Python models written from
//! the Arm ARM. None comes from running kestrel. Every case starts from the
//! same registers and memory, runs one instruction and compares the whole
//! vector file, X0..X3, FPSR.QC and the memory window.

use super::neon_vectors::{CASES, MEM, MEM_BASE, V, X};
use super::tests::setup;
use super::Interpreter;
use crate::{CpuBackend, Exit};

pub struct Case {
    pub group: &'static str,
    pub asm: &'static str,
    pub insn: u32,
    pub fpcr: u64,
    /// Vector registers that change, with their new value.
    pub v: &'static [(u8, u128)],
    /// General registers (X0..X3) that change.
    pub x: &'static [(u8, u64)],
    /// FPSR.QC after the instruction.
    pub qc: bool,
    /// Bytes of the memory window that change (offset from MEM_BASE).
    pub mem: &'static [(u16, u8)],
}

const BRK: u32 = 0xd4200000;

/// Run one case and describe every mismatch.
fn run(case: &Case) -> Vec<String> {
    let (mut s, mut m) = setup(&[case.insn, BRK]);
    s.v = V;
    s.x[..4].copy_from_slice(&X);
    s.fpcr = case.fpcr;
    m.write_bytes(MEM_BASE, &MEM).unwrap();
    let exit = Interpreter::new().run(&mut s, &mut m, 10);
    if exit != Exit::Breakpoint(0) {
        return vec![format!("stopped with {exit:?}")];
    }
    let mut errs = Vec::new();
    let mut want_v = V;
    for &(k, x) in case.v {
        want_v[k as usize] = x;
    }
    for (k, (got, want)) in s.v.iter().zip(want_v).enumerate() {
        if *got != want {
            errs.push(format!("v{k} = {got:#034x}, want {want:#034x}"));
        }
    }
    let mut want_x = X;
    for &(k, x) in case.x {
        want_x[k as usize] = x;
    }
    for (k, (got, want)) in s.x.iter().zip(want_x).enumerate() {
        if *got != want {
            errs.push(format!("x{k} = {got:#x}, want {want:#x}"));
        }
    }
    let qc = s.fpsr >> 27 & 1 != 0;
    if qc != case.qc {
        errs.push(format!("FPSR.QC = {qc}, want {}", case.qc));
    }
    let mut want_mem = MEM;
    for &(k, b) in case.mem {
        want_mem[k as usize] = b;
    }
    let got = m.read_vec(MEM_BASE, MEM.len()).unwrap();
    if got != want_mem {
        let first = (0..MEM.len()).find(|&k| got[k] != want_mem[k]).unwrap();
        errs.push(format!(
            "memory differs first at +{first:#x}: {:#04x}, want {:#04x}",
            got[first], want_mem[first]
        ));
    }
    errs
}

/// Run every case in `group` and report all failures together.
#[track_caller]
fn group(name: &str) {
    let cases: Vec<&Case> = CASES.iter().filter(|c| c.group == name).collect();
    assert!(!cases.is_empty(), "no cases in group {name}");
    let failures: Vec<String> = cases
        .iter()
        .filter_map(|c| {
            let errs = run(c);
            (!errs.is_empty())
                .then(|| format!("{} ({:08x}):\n    {}", c.asm, c.insn, errs.join("\n    ")))
        })
        .collect();
    assert!(
        failures.is_empty(),
        "{} of {} cases failed:\n{}",
        failures.len(),
        cases.len(),
        failures.join("\n")
    );
}

